<template><div class="manager-page"><div class="page-heading"><div><div class="eyebrow">SECURITY</div><h1>修改密码</h1><p>更新登录密码后需要重新进入系统。</p></div></div><div class="card password-card"><el-form :model="form" label-position="top"><el-form-item label="原密码"><el-input v-model="form.password" show-password/></el-form-item><el-form-item label="新密码"><el-input v-model="form.newPassword" show-password/></el-form-item><el-form-item label="确认新密码"><el-input v-model="form.confirmPassword" show-password/></el-form-item><el-button type="primary" round @click="save">确认修改</el-button></el-form></div></div></template>
<script setup>import {reactive} from 'vue';import request from '@/utils/request';import {ElMessage} from 'element-plus';import {useRouter} from 'vue-router';const router=useRouter();const user=JSON.parse(localStorage.getItem('system-user')||'{}');const form=reactive({password:'',newPassword:'',confirmPassword:''});const save=()=>{if(!form.password||!form.newPassword)return ElMessage.warning('请完整填写密码');if(form.newPassword!==form.confirmPassword)return ElMessage.error('两次密码不一致');request.put('/updatePassword',{...user,password:form.password,newPassword:form.newPassword}).then(res=>{if(res.code==='200'){ElMessage.success('密码已修改');localStorage.removeItem('system-user');router.push('/login')}else ElMessage.error(res.msg)})}</script>
<style scoped>.password-card{width:520px;padding:30px}.password-card .el-button{width:140px}@media(max-width:650px){.password-card{width:100%}}</style>
